//! Stable storage for the connection IDs generated by owning URI facades.
const std = @import("std");
const entropy = @import("../internal/secure_random.zig");
const Options = @import("handshake.zig").ClientOptions;

pub const Storage = struct {
    bytes: [16]u8 = undefined,

    /// Generate only missing IDs, sharing one entropy operation and budget.
    /// The caller keeps this storage alive for the complete handshake.
    pub fn prepareBefore(self: *Storage, io: std.Io, options: *Options, deadline: ?std.Io.Clock.Timestamp) entropy.BeforeError!void {
        const original = options.original_destination_connection_id.len == 0;
        const local = options.local_connection_id.len == 0;
        if (!original and !local) return;
        const begin: usize = if (original) 0 else 8;
        const end: usize = if (local) 16 else 8;
        try entropy.fillBefore(io, self.bytes[begin..end], deadline);
        // Publish the borrowed slices only after successful, timely entropy.
        if (original) options.original_destination_connection_id = self.bytes[0..8];
        if (local) options.local_connection_id = self.bytes[8..16];
    }
};

test "startup entropy connection IDs preserve configured IDs and share one fill" {
    const Probe = @import("../internal/secure_random/tests.zig").Probe;
    inline for (0..4) |missing| {
        var probe: Probe = .{};
        var storage: Storage = .{};
        var options: Options = .{
            .original_destination_connection_id = if (missing & 1 != 0) "" else "original",
            .local_connection_id = if (missing & 2 != 0) "" else "local",
        };
        try storage.prepareBefore(probe.io(), &options, null);
        try std.testing.expectEqual(@as(usize, if (missing == 0) 0 else 1), probe.calls);
        try std.testing.expectEqualSlices(u8, if (missing & 1 != 0) &(@as([8]u8, @splat(0xa5))) else "original", options.original_destination_connection_id);
        try std.testing.expectEqualSlices(u8, if (missing & 2 != 0) &(@as([8]u8, @splat(0xa5))) else "local", options.local_connection_id);
    }
}

test "startup entropy connection ID failure retains the caller's options" {
    var probe: @import("../internal/secure_random/tests.zig").Probe = .{ .fail_entropy = true };
    var storage: Storage = .{};
    var options: Options = .{ .original_destination_connection_id = "", .local_connection_id = "local" };
    const expected = options;
    try std.testing.expectError(error.EntropyUnavailable, storage.prepareBefore(probe.io(), &options, null));
    try std.testing.expectEqualDeep(expected, options);
}
